_url": "https://www.emerald.com/insight/content/doi/10.1108/JD-09-2023-0173/full/pdf?title=curiosity-and-information-seeking-behaviour-a-review-of-psychological-research-and-a-comparison-with-the-information-science-literature", "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.1108/jd-09-2023-0173", "doi": "https://doi.org/10.1108/jd-09-2023-0173", "is_oa": true, "landing_page_url": "https://doi.org/10.1108/jd-09-2023-0173", "pdf_url": "https://www.emerald.com/insight/content/doi/10.1108/JD-09-2023-0173/full/pdf?title=curiosity-and-information-seeking-behaviour-a-review-of-psychological-research-and-a-comparison-with-the-information-science-literature", "source": {"id": "https://openalex.org/S10082577", "display_name": "Journal of Documentation", "issn_l": "0022-0418", "issn": ["0022-0418", "1758-7379"], "is_oa": false, "is_in_doaj": false, "is_core": true, "listed_in": ["abdc-b", "anvur-class-a", "anvur-scientific", "cwts-core", "fnege-4", "jufo-3", "norway-2", "poland-100", "russia-white-list-1", "vabb-shw"], "host_organization": "https://openalex.org/P4310319811", "host_organization_name": "Emerald Publishing Limited", "host_organization_lineage": ["https://openalex.org/P4310319811"], "host_organization_lineage_names": ["Emerald Publishing Limited"], "type": "journal"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Journal of Documentation", "raw_type": "journal-article"}, "abstract": "Purpose The aim of this paper is to review the psychological literature on curiosity and its relationship to information-seeking behaviour, and compare this with the information science literature on the same subject. Design/methodology/approach The approach adopted is that of a comparative literature review, with an analysis of the papers retrieved in terms of their theoretical approach, context, study population and research method. Findings Curiosity is understood as a multi-faceted cognitive trait in humans and the relationship to information-seeking behaviour is explored through an exploration of other personality characteristics. There is very little citation of the information science literature in the psychological papers, and only a little more citation of the psychological literature in the information science papers. Originality/value The author is not aware of any similar exploration of the literature on curiosity."}]", "excerpt_truncated": true, "source_sha256": "475454c5b73cc94cff85e228a82fcb423592ad338421861b95915e83c82e52f8", "verification_required": true, "topic_domain": "unassigned_inquiry", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1002/tea.70019", "doi:10.1108/jd-09-2023-0173/full/pdf", "doi:10.1108/jd-09-2023-0173", "openalex:W4414067814"], "source_candidates": ["https://doi.org/10.1002/tea.70019", "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/tea.70019", "https://doi.org/10.1108/jd-09-2023-0173"], "source_candidate_identities": {}}
